from lib import *
S = SS('w52')
steps = [
    step("初始拥塞窗口:新连接建立后、发任何数据之前,读发送方 tcp_info 的 snd_cwnd:lo0 上是 163321 字节,maxseg 16332 字节,正好 10.0 个 MSS;en0 到 example.com 是 13880 字节、maxseg 1388 字节,也是 10.0 个 MSS——与 RFC 6928 的初始窗口 10 个 MSS 一致。snd_ssthresh 初始是 1073725440(约 1 GiB,近似无穷大),意思是一开始没有慢启动阈值,窗口会一直翻倍直到丢包。", t=tl(S(1)), mark=lidx(S(1), 'lo0:snd_cwnd', 'en0 到 example.com'), done=lidx(S(1), 'lo0:snd_cwnd'), b=bars([['lo0 · 初始 cwnd', 10, '10 个 MSS'], ['en0 · 初始 cwnd', 10, '10 个 MSS']], 10, mark=[], done=[0, 1]), kv=KV([['初始窗口', '10 个 MSS(lo0 163,321 字节;en0 13,880 字节)'], ['初始 ssthresh', '1,073,725,440:近似无穷大'], ['RFC 6928', '初始窗口 10 个 MSS']], ['初始窗口'])),
    step("慢启动与丢包:往返 100 ms(netlab 每个方向 50 ms)、0.3% 随机丢包的回环上传输 8 秒,共传 53.8 MB,每 10 ms 读一次发送方的 snd_cwnd。开头 0.5 秒(5 个 RTT):cwnd 依次约 10、10、19、38、99、99 个 MSS——差不多每个 RTT 翻倍,这是指数增长的“慢启动”;0.6 秒时到 190 个 MSS(3,103,497 字节)。0.8 秒时累计第 1 次重传,1.0 秒时 cwnd 掉到 1 个 MSS(16,332 字节),ssthresh 设成 2,939,760;1.5 秒时 cwnd 恢复到 106 个 MSS,2.0 秒 110 个;3.0 秒 42 个、4.0 秒 25 个、6.0 秒 19 个、8.0 秒 20 个,累计重传 11 个包。srtt 稳定后约 101 ms。", t=tl(S(2)), mark=lidx(S(2), '       0.20 ', '       0.30 ', '       0.60 ', '       1.00 '), done=lidx(S(2), '传输 53.8 MB', '       0.00 ', '       8.00 ', '开头 0.5 秒'), b=bars([['0.0 秒', 10, '10 个 MSS'], ['0.2 秒', 19, '19'], ['0.3 秒', 38, '38'], ['0.4 秒', 99, '99'], ['0.6 秒', 190, '190'], ['1.0 秒(丢包后)', 1, '1']], 190, mark=[5], done=[0, 1, 2, 3, 4]), kv=KV([['0 → 0.6 秒', '10 → 190 个 MSS:每个 RTT 约翻倍'], ['第一次丢包后', 'cwnd 掉到 1 个 MSS(1.0 秒)'], ['之后', '1.5 秒 106 → 8 秒 20 个 MSS'], ['重传', '共 11 个包']], ['第一次丢包后'])),
    step("丢包以后:8 秒内检测到 8 次 cwnd 明显下降。第 1 次(0.93 秒)是 cwnd 从 2,939,760(180 个 MSS)直接掉到 16,332(1 个 MSS)——降后 / 降前 = 0.01,这是超时重传(RTO)的特征,不是快速恢复。其后 7 次都是快速恢复:1.65 秒 153 → 107 个 MSS(0.70)、2.15 秒 112 → 78(0.70)、3.24 秒 43 → 31(0.72)、3.97 秒 35 → 25(0.71)、4.55 秒 27 → 20(0.74)、5.89 秒 27 → 19(0.70)、7.40 秒 26 → 18(0.69),每次降完 ssthresh 都设成降后的 cwnd。7 次降幅的中位数 0.70——Reno 是 0.5,CUBIC 是 0.7,所以本机默认用的是 CUBIC(net.inet.tcp.cubic_sockets 显示有 445 个 CUBIC 套接字)。", t=tl(S(3)), mark=lidx(S(3), '0.93 秒', '1.65 秒', '2.15 秒', '3.24 秒'), done=lidx(S(3), '8 秒内检测到', '降后 / 降前的中位数', 'net.inet.tcp.cubic_sockets', '3.97 秒', '4.55 秒', '5.89 秒', '7.40 秒'), b=bars([['超时(0.93 秒)降后/降前', 0.01, '0.01'], ['快速恢复中位数', 0.70, '0.70'], ['Reno 的 β', 0.5, '0.5'], ['CUBIC 的 β', 0.7, '0.7']], 1, mark=[0], done=[1, 2, 3]), kv=KV([['超时重传', 'cwnd → 1 个 MSS(0.01)'], ['快速恢复', 'β ≈ 0.70(7 次中位数)'], ['Reno / CUBIC', '0.5 / 0.7:本机是 CUBIC'], ['ssthresh', '降后 = cwnd']], ['快速恢复'])),
    step("拥塞避免阶段 cwnd 的增长速度:取几段没有丢包的时间拟合斜率。0.0~0.9 秒这一段(包含慢启动):cwnd 从 67 个 MSS 到 180 个 MSS,斜率 214.0 个 MSS/秒,每个 RTT 增加约 21.4 个 MSS;4.5~5.9 秒:从 21 个 MSS 到 27 个,斜率 7.9 个 MSS/秒,每个 RTT 增加约 0.8 个;5.9~7.4 秒:从 22 到 26 个 MSS,斜率 4.5 个 MSS/秒,每个 RTT 增加约 0.4 个。也就是说拥塞避免阶段 cwnd 每个 RTT 只涨不到 1 个 MSS(线性增长或更慢;CUBIC 在接近上次丢包时的窗口时增长更平缓)。AIMD 的含义:慢启动指数增长,拥塞避免线性增长,丢包后乘性减小。", t=tl(S(4)), mark=lidx(S(4), '4.5~5.9 秒这一段', '5.9~7.4 秒这一段'), done=lidx(S(4), '0.0~0.9 秒这一段', '慢启动:cwnd 每个 RTT 翻倍'), b=bars([['0.0~0.9 秒(含慢启动)· 每 RTT', 21.4, '+21.4 个 MSS'], ['4.5~5.9 秒 · 每 RTT', 0.8, '+0.8 个 MSS'], ['5.9~7.4 秒 · 每 RTT', 0.4, '+0.4 个 MSS']], 21.4, mark=[1, 2], done=[0]), kv=KV([['慢启动', '每个 RTT 翻倍'], ['拥塞避免', '每个 RTT 增加不到 1 个 MSS(0.4~0.8)'], ['丢包', '乘性减小 β ≈ 0.7']], ['拥塞避免'])),
]
A = mkartw('w52', 52, '网络协议,TCP,拥塞控制,慢启动,拥塞避免,cwnd,CUBIC,真实验证,动画演示',
    '初始拥塞窗口 10 个 MSS;慢启动每个 RTT 约翻倍(10 → 190 个 MSS);超时重传使 cwnd 掉到 1 个 MSS,快速恢复降后 / 降前中位数 0.70(CUBIC),拥塞避免阶段每 RTT 只涨 0.4~0.8 个 MSS。',
    '拥塞窗口(cwnd)是怎么长大的、什么时候缩小?慢启动真的是指数增长吗?丢包后降到一半还是降到 0.7?这篇每 10 毫秒读一次发送方内核里的 cwnd,在 100 ms 往返、0.3% 丢包的回环上记下一次传输的全过程。',
    [('10 → 190 个 MSS', '0.6 秒内慢启动把 cwnd 从初始窗口放大的倍数:每个 RTT 约翻倍'), ('0.70', '快速恢复后 cwnd 降后 / 降前的中位数(7 次),说明本机用 CUBIC 而不是 Reno 的 0.5'), ('1 个 MSS', '超时重传(RTO)时 cwnd 的落点——和快速恢复的 0.7 不同')],
    [('初始窗口', '<p>新连接的 cwnd 是 10 个 MSS,ssthresh 近似无穷大。</p>'),
     ('慢启动', '<p>每收到 ACK 就增加 cwnd,等于每个 RTT 翻倍,直到丢包或到达 ssthresh。</p>'),
     ('丢包反应', '<p>超时重传让 cwnd 回到 1 个 MSS;快速恢复只降到 0.7 倍(CUBIC),同时 ssthresh 设成降后的值。</p>'),
     ('拥塞避免', '<p>之后每个 RTT 只增长不到 1 个 MSS;CUBIC 接近上次丢包窗口时增长更平缓。</p>')],
    steps,
    [ENV_W + '。全部在 lo0 上,往返 100 ms 与 0.3% 丢包由 netlab 注入;cwnd / ssthresh / srtt 来自发送方套接字的 TCP_CONNECTION_INFO,每 10 ms 采样一次(Python 线程的采样间隔会有抖动);丢包是随机的,每次运行的曲线不同,本篇的数字取自最后一次运行',
     '没有验证:BBR 或 Reno 的对照(下一篇);cwnd 与接收窗口、发送缓冲区的相互限制;拥塞避免阶段 CUBIC 的三次曲线是否完全符合公式;ECN 标记引起的 cwnd 下降;en0 真实网络上的 cwnd 曲线'],
    '慢启动与拥塞避免')
